def parse_hours_string(hours_str):
    """Parse the hours string from Yelp business table into a dictionary."""
    if not hours_str or hours_str == 'None':
        return {}
    try:
        # Convert single quotes to double quotes for valid JSON
        hours_json = hours_str.replace("'", '"')
        return json.loads(hours_json)
    except (json.JSONDecodeError, TypeError):
        return {}

def time_in_range(start_str, end_str, check_time):
    """Check if a given time falls within the start-end range."""
    def parse_time(t):
        # Handle cases like '15:00', '3:00', '3PM', etc.
        t = t.strip()
        if ':' not in t:
            if 'AM' in t.upper() or 'PM' in t.upper():
                return datetime.strptime(t, '%I%p').time()
            else:
                # Assume 24-hour format without minutes
                hour = int(t)
                return time(hour % 24, 0)
        else:
            if 'AM' in t.upper() or 'PM' in t.upper():
                return datetime.strptime(t, '%I:%M%p').time()
            else:
                parts = t.split(':')
                hour = int(parts[0])
                minute = int(parts[1]) if len(parts) > 1 else 0
                return time(hour % 24, minute)

    try:
        start_time = parse_time(start_str)
        end_time = parse_time(end_str)

        # Handle overnight hours (e.g., 22:00-02:00)
        if end_time <= start_time:
            # Spans midnight
            return check_time >= start_time or check_time <= end_time
        else:
            return start_time <= check_time <= end_time
    except:
        return False

