from datetime import datetime, time

def parse_hours(hours_str):
    """Parse the hours string into a dictionary."""
    if not hours_str or hours_str == 'None':
        return {}
    try:
        # The hours field is stored as a string that looks like a dict
        return json.loads(hours_str.replace("'", '"'))
    except json.JSONDecodeError:
        return {}

def time_in_range(start, end, x):
    """Check if time x is in the range [start, end]. Handles overnight ranges."""
    if start <= end:
        return start <= x <= end
    else:
        return start <= x or x <= end

def is_open_during_window(hours_dict, window_start, window_end):
    """Check if the business is open at any point during the given time window."""
    for day_hours in hours_dict.values():
        if '-' not in day_hours:
            continue
        open_time_str, close_time_str = day_hours.split('-')
        try:
            open_time = datetime.strptime(open_time_str, '%H:%M').time()
            close_time = datetime.strptime(close_time_str, '%H:%M').time()
        except ValueError:
            continue

        # Check if the window overlaps with business hours
        # We check if any time in [window_start, window_end] is within [open_time, close_time]
        if time_in_range(open_time, close_time, window_start) or \
           time_in_range(open_time, close_time, window_end) or \
           (open_time <= window_start and close_time >= window_end):
            return True
    return False

