    """Parse hours string and return a dictionary of day -> (open_time, close_time)"""
    if not hours_str:
        return {}

    try:
        # Try to parse as JSON
        hours_dict = json.loads(hours_str)
        parsed_hours = {}

        for day, hours_range in hours_dict.items():
            if hours_range == 'Closed':
                continue

            if '-' in hours_range:
                open_str, close_str = hours_range.split('-')
                # Handle 24-hour format conversion
                open_time = datetime.strptime(open_str, '%H:%M').time()
                close_time = datetime.strptime(close_str, '%H:%M').time()
                parsed_hours[day] = (open_time, close_time)
        return parsed_hours
    except (json.JSONDecodeError, ValueError):
        return {}

def is_open_at_time(hours_dict, target_time):
    """Check if business is open at target_time on any day"""
    for day, (open_time, close_time) in hours_dict.items():
        # Handle cases where closing time is next day (e.g., 23:00-02:00)
        if close_time < open_time:
            # Spans midnight - check if target is after open OR before close
            if target_time >= open_time or target_time <= close_time:
                return True
        else:
            # Normal case - check if target is between open and close
            if open_time <= target_time <= close_time:
                return True
    return False

